import{_ as p,r as n,o,c as r,e as t,a as i,s as l}from"./chunks/framework.CXcwiNg-.js";const f=JSON.parse('{"title":"Object List Inspector Type - October CMS - 4.x","titleTemplate":false,"description":"Inspector Type","frontmatter":{"subtitle":"Inspector Type","shortname":"Object List"},"headers":[],"relativePath":"4.x/element/inspector/type-objectlist.md","filePath":"4.x/element/inspector/type-objectlist.md"}'),c={name:"4.x/element/inspector/type-objectlist.md"};function u(g,s,d,k,q,y){const a=n("pre-heading"),e=n("post-heading");return o(),r("div",null,[t(a),s[0]||(s[0]=i("h1",null,"Object List Inspector Type",-1)),t(e),s[1]||(s[1]=l(`<p>The <code>objectList</code> inspector type allows users to create multiple objects with a pre-defined structure. For example, it could be used for creating a list of person, where each person has a name and address.</p><p>The properties of objects that can be created with the editor are defined with <code>itemProperties</code> parameter. The parameter should contain an array of properties, similar to an inspector configuration array. Another required parameter is <code>titleProperty</code>, which identifies a property that should be used as a title in inspector UI.</p><p>The array of properties defined with <code>itemProperties</code> supports all property types.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">defineProperties</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;address&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
            <span class="token string single-quoted-string">&#39;title&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Address&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;type&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;objectList&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;titleProperty&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;fullName&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;itemProperties&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
                <span class="token string single-quoted-string">&#39;fullName&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
                    <span class="token string single-quoted-string">&#39;title&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Full Name&#39;</span><span class="token punctuation">,</span>
                    <span class="token string single-quoted-string">&#39;type&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;string&#39;</span>
                <span class="token punctuation">]</span><span class="token punctuation">,</span>
                <span class="token string single-quoted-string">&#39;address&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
                    <span class="token string single-quoted-string">&#39;title&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Address&#39;</span><span class="token punctuation">,</span>
                    <span class="token string single-quoted-string">&#39;type&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;string&#39;</span>
                <span class="token punctuation">]</span>
            <span class="token punctuation">]</span>
        <span class="token punctuation">]</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>By default the generated output is a non-associative array, for example:</p><div class="language-json extra-class"><pre class="language-json"><code><span class="token property">&quot;people&quot;</span><span class="token operator">:</span> <span class="token punctuation">[</span>
    <span class="token punctuation">{</span><span class="token property">&quot;fullName&quot;</span><span class="token operator">:</span> <span class="token string">&quot;John Smith&quot;</span><span class="token punctuation">,</span> <span class="token property">&quot;address&quot;</span><span class="token operator">:</span> <span class="token string">&quot;Palo Alto&quot;</span><span class="token punctuation">}</span><span class="token punctuation">,</span>
    <span class="token punctuation">{</span><span class="token property">&quot;fullName&quot;</span><span class="token operator">:</span> <span class="token string">&quot;Bart Simpson&quot;</span><span class="token punctuation">,</span> <span class="token property">&quot;address&quot;</span><span class="token operator">:</span> <span class="token string">&quot;Springfield&quot;</span><span class="token punctuation">}</span>
<span class="token punctuation">]</span>
</code></pre></div><p>The following <a href="./../inspector-types.html">configuration values</a> are commonly used and supported.</p><div class="table"><table tabindex="0"><thead><tr><th>Property</th><th>Description</th></tr></thead><tbody><tr><td><strong>title</strong></td><td>title for the property.</td></tr><tr><td><strong>description</strong></td><td>a brief description of the property, optional.</td></tr><tr><td><strong>keyProperty</strong></td><td>use this property key as the title, found in the <strong>itemProperties</strong> definitions.</td></tr><tr><td><strong>titleProperty</strong></td><td>use this property name as the title, found in the <strong>itemProperties</strong> definitions.</td></tr><tr><td><strong>itemProperties</strong></td><td>an array of nested property definitions.</td></tr></tbody></table></div><div class="custom-block warning"><p>This type does not support the external parameter editor as specified by the <code>showExternalParam</code> property.</p></div><div class="custom-block warning"><p>The Object List inspector type doesn&#39;t support default values.</p></div><p>If the result value should be an associative array (object), use the <code>keyProperty</code> configuration option. The option value should refer to a property that should be used as a key. The key property can use only the string or drop-down editors, its value should be unique and cannot be empty.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">defineProperties</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;address&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
            <span class="token string single-quoted-string">&#39;title&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Address&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;type&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;objectList&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;titleProperty&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;fullName&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;keyProperty&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;login&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;itemProperties&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
                <span class="token string single-quoted-string">&#39;fullName&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
                    <span class="token string single-quoted-string">&#39;title&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Full Name&#39;</span><span class="token punctuation">,</span>
                    <span class="token string single-quoted-string">&#39;type&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;string&#39;</span>
                <span class="token punctuation">]</span><span class="token punctuation">,</span>
                <span class="token string single-quoted-string">&#39;login&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
                    <span class="token string single-quoted-string">&#39;title&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Login&#39;</span><span class="token punctuation">,</span>
                    <span class="token string single-quoted-string">&#39;type&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;string&#39;</span>
                <span class="token punctuation">]</span><span class="token punctuation">,</span>
                <span class="token string single-quoted-string">&#39;address&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
                    <span class="token string single-quoted-string">&#39;title&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Address&#39;</span><span class="token punctuation">,</span>
                    <span class="token string single-quoted-string">&#39;type&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;string&#39;</span>
                <span class="token punctuation">]</span>
            <span class="token punctuation">]</span>
        <span class="token punctuation">]</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>The <code>login</code> property in the example above will be used as a key in the result value:</p><div class="language-json extra-class"><pre class="language-json"><code><span class="token property">&quot;people&quot;</span><span class="token operator">:</span> <span class="token punctuation">{</span>
    <span class="token property">&quot;john&quot;</span><span class="token operator">:</span> <span class="token punctuation">{</span><span class="token property">&quot;fullName&quot;</span><span class="token operator">:</span> <span class="token string">&quot;John Smith&quot;</span><span class="token punctuation">,</span> <span class="token property">&quot;address&quot;</span><span class="token operator">:</span> <span class="token string">&quot;Palo Alto&quot;</span><span class="token punctuation">}</span><span class="token punctuation">,</span>
    <span class="token property">&quot;bart&quot;</span><span class="token operator">:</span> <span class="token punctuation">{</span><span class="token property">&quot;fullName&quot;</span><span class="token operator">:</span> <span class="token string">&quot;Bart Simpson&quot;</span><span class="token punctuation">,</span> <span class="token property">&quot;address&quot;</span><span class="token operator">:</span> <span class="token string">&quot;Springfield&quot;</span><span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div>`,14))])}const m=p(c,[["render",u]]);export{f as __pageData,m as default};
